cout << R"(Un ruido ahogado se escucha desde el pasillo. Parecen pisadas.Abris la puerta con cierta molestia. 
Ves a tu hija abriendo la puerta de su pieza de puntitas de pie, intentando no hacer ruido. 
Lo primero que hace al notar tu presencia es, ademas de abrir los ojos como platos, 
cubrirse rápidamente la cabeza con un gorro de lana. 
<< ¿¡Papa!? Pense.. que estabas durmiendo!! >> Casi gritando desesperada, con cierto panico. 
Lo que mas te llama la atencion son algunos mechones de pelo esparcidos por su remera. 
Y claro, la repentina falta de su pelo largo, que intenta ocultar miserablemente con su gorro. 
Se da cuenta, porque enseguida exclama 
<< ¡Es solo un poco más corto, queria ver como me quedaba! ¡Pero el pelo crece! No esperaba que me vieras hasta mañana… >>.
)" << endl;
cout << "1.¡▒▒▒▒▒▒, ultimamente no haces mas que darme la contra en todo! ¿Por que no podes actuar como una nena normal? " << endl;
cout << "2. Pareces una marimacha, ▒▒▒▒▒, ni siquiera quiero ver el desastre que ocultas con el gorro. " << endl;
cout << "\n==================================================================================" << "\n";
