    cout << R"(Año 2016.
Son  alrededor de las seis de la tarde, terminaste de preparar la 
merienda y estas sirviendolo en la mesa  de comedor donde tu hija
esta sentada.  Una  chocolatada caliente para ella, y para vos un 
buen  cafe  amargo.  Despues de  hacerle la pregunta de todos los 
dias sobre como fue su dia en el colegio, ella tehace acordar que
hoy  eran las  charlas de ESI.  Lo  habias olvidado por  completo.
Mientras  le da un sobo a su taza,  ves que tiene muchas ganas de 
contarte  mas al respecto.  Cuando vos ibas al colegio, este tipo 
de charlas hubiesen sonado a locuras y perversión a las infancias,
pero genuinamente no ves de  malo concientizar  a los más jóvenes, 
así  puede  ayudar a  bajar la  tasa  de  embarazos  adolescentes, 
por ejemplo. Procedes a escucharla.

)" << endl;


cout << "Presiona E y Enter para poder escucharla: ";
cin >> accion;

