    cout << R"(Año 2019.
Es la medianoche del domingo,  no ves la hora de dormir ya y 
recuperar  la energía  para la semana entrante. Muchas cosas 
pasan por tu cabeza, como las interminables juntas de trabajo
que te  dan migrañas  de solo pensar.  También  se te cruzan 
pensamientos  sobre tu hija.  Últimamente la notas diferente,
la ves un poco más inhibida,  algo normal  en un adolescente,
pero sentís que hay algo más.  Te preocupa  que esté pasando
por  algo grave  y  no tener las herramientas o su confianza
para poder ayudarla.
)" << endl;

