    cout << R"(
Hablando de Roma, ves desde la puerta  entreabierta a tu hija 
yéndose  de  puntitas de pie por  el pasillo.  Al levantar tu 
curiosidad, te  acercas  a la puerta.

Lo primero que hace al notar tu presencia es, además de abrir 
los ojos como platos,  cubrirse  rápidamente la cabeza con un 
gorro de lana.

<< ¿¡Papá!? Pensé... que estabas durmiendo!! >> Dice con una risita nerviosa.
Lo que más te llama la atención son  algunos mechones de pelo 
esparcidos por su  remera.  Y claro, la repentina falta de su 
pelo largo, que  intenta  ocultar miserablemente con su gorro. 
Efectivamente, se estaba cortando el pelo ella sola. Le pedís 
amablemente que se saque el gorro para poder verla mejor.
)" << endl;

    cout << "\n==================================================================================" << "\n";

    cout << "Presiona Enter para verla sin el gorro...";
    cin.ignore();
    cin.get();

    system("clear");

    cout << "\n==================================================================================" << "\n";

