    cout << R"(
Ella se queda algo atónita, pero aliviada.  No esperaba 
esa respuesta. Vos te reís porque te hace acordar a vos
de chiquito, con un corte  que te hizo tu hermano mayor
antes de que  les saquen la foto escolar  en el colegio.
Se dirigen al baño y le pedís que te alcance tu máquina
de afeitar para  arreglarle el  corte, aquella que está
en la repisa del baño. Y bueno,  tocará aplazar el irse
a dormir,  porque el deber  llama.  Tu hija te necesita. 
)" << endl;

    cout << "\n==================================================================================" << "\n";

    cout << "Presiona Enter para continuar a cortarle el pelo...";
    cin.ignore();
    cin.get();

    estado = 3;
