    cout << R"(
Sin pensarlo  mucho se lanza directamente a  tus brazos. 
Rompe en un  llanto al instante.  Uno  de alivio.
No podés evitar que tus ojos tambien se pongan vidriosos.
Lo abrazás con mucha fuerza, como si de la cosa mas fragil
y delicado se tratase, como si la niña, o mejor dicho niño, 
de 8 años que siempre tenias que estar cuidando volviese a
fundirse en tu abrazo, comunicándole que vas a estar siempre
para él, tu precioso hijo.

Luego del fuerte abrazo, ▒▒▒▒▒▒ tiene algo más para decirte.
<< Che, pa, a todo esto… >> 

Toma  unos  segundos  para  aclararse la garganta  tragando 
saliva y, con mucha firmeza, suelta: 
<< ¡Quiero que vos me ayudes a elegir mi nombre! >>
)" << endl;

